mapper.select:
select *
from contract_supplier_payment
where bool_delete_enum = 0

    and order_id = #{orderId}


    and property_type & #{propertyType} > 0


    and payment_unit_id =  #{paymentUnitId}


    and receiving_unit_id = #{supplierId}


    and receiving_unit_id = 0


    and audit_status = #{auditStatus}


    and date(create_time) >= date(#{startDate})


    and date(create_time) <= date(#{endDate})

order by audit_status, id desc

        select
        IFNULL(sum(payment_amount),0)
        from contract_supplier_payment
        where bool_delete_enum = 0

        
            and supplier_id = #{supplierId}
        
        
            and order_id = #{orderId}
        

        
            and property_type in
            
                #{propertyType}
            
        

        
            and audit_status = #{auditStatus}

select ifnull(sum(actually_payment_amount), 0)
from contract_supplier_payment
where bool_delete_enum = 0
  and order_id = #{orderId}
  and property_type = #{propertyType}
  and audit_status = 2

select *
from contract_supplier_payment
where bool_delete_enum = 0
and property_type = #{propertyType}

    and order_id = #{orderId}


    and payment_unit_id = #{paymentUnitId}


    and receiving_unit_id = #{receivingUnitId}

and audit_status = 2
order by id desc limit 1

choose.otherwise:
SELECT temp.supplier_id AS id, (CASE temp.bool_personal_enum when 0 then ss.name else '个人' end) AS supplier_name, IFNULL( sum( temp.freight ), 0 ) AS freight, count(*) AS train_number FROM ( SELECT sp.supplier_id, sp.bool_personal_enum, c.total_price AS freight FROM mes_building_cargo_list AS c LEFT JOIN mes_building_supplier_price AS sp ON c.supplier_price_id = sp.id WHERE c.bool_delete_enum = 0 AND c.status IN ( 4, 8 )
AND ( c.project_id IN (SELECT id from contract_project where bool_delete_enum = 0 AND name LIKE concat ('%',#{name},'%')) OR sp.supplier_id IN ( SELECT id FROM scm_supplier WHERE bool_delete_enum = 0 AND name LIKE concat ('%',#{name},'%')) )
and date(c.create_time) >= date(#{startDate})
and date(c.create_time) <= date(#{endDate})
UNION ALL
SELECT supplier_id, 0 AS bool_personal_enum, freight FROM scm_logistics_order WHERE bool_delete_enum = 0 AND inbound_review_status = 2
AND ( purchase_SN like concat ('%',#{name},'%') OR supplier_id IN ( SELECT id FROM scm_supplier WHERE bool_delete_enum = 0 AND name like concat ('%',#{name},'%') ) )
and DATE(create_time) >= #{startDate}
and DATE(create_time) <= #{endDate}
) AS temp left join scm_supplier AS ss ON temp.supplier_id = ss.id GROUP BY temp.supplier_id, temp.bool_personal_enum

mapper.select:
SELECT temp.* FROM ( SELECT c.id, c.audit_time AS ship_date, c.license_plate, c.actual_weight AS loading_weight, 2 type, c.car_model, c.driver_name, c.driver_phone, sp.bool_personal_enum, ifnull( c.change_freight, 1 ) change_freight, c.total_price AS freight, CONCAT( cp.serial_number, "+", cp.short_name ) AS projectName FROM mes_building_cargo_list c LEFT JOIN mes_building_supplier_price AS sp ON sp.id = c.supplier_price_id LEFT JOIN contract_project AS cp ON cp.id = c.project_id AND sp.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 AND c.`status` IN (4,8)
and cp.name like concat('%', #{projectName}, '%')
and sp.supplier_id = #{supplierId}
and date(c.audit_time) >= date(#{startDate})
and date(c.audit_time) <= date(#{endDate})
) temp order by temp.ship_date desc

choose.when:
select slo.id, slo.supplier_id, ss.name as supplier_name, slo.create_time as ship_date, slo.license_plate, slo.loading_weight, 1 type, 0 AS bool_personal_enum, slo.change_freight change_freight, slo.freight from scm_logistics_order as slo left join scm_supplier as ss on slo.supplier_id = ss.id and ss.bool_delete_enum = 0 where slo.bool_delete_enum = 0 and slo.inbound_review_status = 2 and slo.purchase_id = #{id}
and slo.supplier_id = #{supplierId}
and DATE(slo.create_time) >= #{startDate}
and DATE(slo.create_time) <= #{endDate}
and slo.change_freight = #{changeFreight}
order by slo.create_time desc

SELECT temp.* FROM (select c.id, c.audit_time AS ship_date, c.license_plate, c.actual_weight as loading_weight, 2 type, c.car_model, c.driver_name, c.driver_phone, sp.bool_personal_enum, ifnull(c.change_freight, 1) change_freight, c.total_price as freight, sp.supplier_id, (select name from scm_supplier where bool_delete_enum = 0 and id = sp.supplier_id) as supplier_name FROM mes_building_cargo_list c LEFT JOIN mes_building_supplier_price AS sp on sp.id = c.supplier_price_id and sp.bool_delete_enum = 0 where c.bool_delete_enum = 0 AND c.`status` IN ( 4, 8 ) and c.project_id = #{id}
and sp.supplier_id = #{supplierId}
and (c.change_freight = 1 or c.change_freight is null)
and c.change_freight = #{changeFreight}
and DATE(c.audit_time) >= #{startDate}
and DATE(c.audit_time) <= #{endDate}
) temp order by temp.ship_date desc

select p.name, c.audit_time as ship_date, c.license_plate, c.actual_weight as loading_weight, c.car_model, c.driver_name, c.driver_phone, sp.bool_personal_enum, IFNULL(c.change_freight,${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ChangeFreightEnum@FREIGHT_RETAIN.getType()}) changeFreight, c.total_price as freight, 2 type from mes_building_cargo_list c inner join mes_building_supplier_price sp on sp.id = c.supplier_price_id and sp.bool_delete_enum = 0 and sp.bool_personal_enum = 1 Inner join mes_building_licence_plate as lp on lp.license_plate = sp.license_plate and lp.bool_delete_enum = 0 left join contract_project p on p.id = c.project_id and p.bool_delete_enum = 0 where c.bool_delete_enum = 0 AND c.shipment_status IN ( 1, 4 ) AND c.`status` IN ( 4, 8 )
and lp.id = #{id}
and p.contract_sign_body_id = #{branchCompanyId}
and DATE(c.audit_time) >= #{startDate}
and DATE(c.audit_time) <= #{endDate}

select temp.* from ( select c.project_id AS id, cp.name, c.audit_time as ship_date, c.license_plate, c.actual_weight as loading_weight, c.car_model, c.driver_name, c.driver_phone, sp.bool_personal_enum, IFNULL(c.change_freight, 1) change_freight, c.total_price as freight, 2 type from mes_building_cargo_list c inner join contract_project cp on cp.id = c.project_id and cp.bool_delete_enum = 0 left join mes_building_supplier_price sp on sp.id = c.supplier_price_id and sp.bool_delete_enum = 0 where c.bool_delete_enum = 0 AND c.`status` IN ( 4, 8 )
and sp.supplier_id = #{id}
and sp.bool_personal_enum = 1
and cp.contract_sign_body_id = #{branchCompanyId}
and (c.change_freight = 1 or c.change_freight is null)
and c.change_freight = #{changeFreight}
and DATE(c.audit_time) >= #{startDate}
and DATE(c.audit_time) <= #{endDate}
union all select slo.purchase_id AS id, slo.purchase_sn name, slo.create_time ship_date, slo.license_plate, slo.loading_weight, 0 AS bool_personal_enum, null car_model, null driver_name, null driver_phone, 1 change_freight, slo.freight, 1 type from scm_logistics_order as slo inner join scm_purchase_order as spo on slo.purchase_id = spo.id and spo.bool_delete_enum = 0 where slo.bool_delete_enum = 0 and slo.inbound_review_status = 2 and slo.supplier_id = #{id}
and spo.branch_company_id = #{branchCompanyId}
and DATE(slo.create_time) >= #{startDate}
and DATE(slo.create_time) <= #{endDate}
) as temp order by temp.ship_date desc

mapper.select:
SELECT
IFNULL(SUM(apply_amount),0)
FROM
contract_supplier_payment
WHERE bool_delete_enum = 0
AND audit_status = 2
and property_type = #{propertyType}

    AND receiving_unit_id = #{supplierId}


    AND payment_unit_id = #{paymentUnitId}

choose.when:
SELECT
IFNULL(SUM(csp.actually_payment_amount),0)
FROM
contract_supplier_payment AS csp
INNER JOIN scm_purchase_order AS spo on csp.order_id = spo.id AND spo.bool_delete_enum = 0
WHERE csp.bool_delete_enum = 0
AND csp.audit_status = 2
and csp.property_type = #{propertyType}

    AND csp.receiving_unit_id = #{supplierId}


    AND csp.payment_unit_id = #{paymentUnitId}

SELECT IFNULL(SUM(cspd.actually_payment_amount),0) FROM contract_supplier_payment_detail as cspd WHERE cspd.bool_delete_enum = 0 AND cspd.audit_status = 2
AND cspd.receiving_unit_id = #{supplierId}
AND cspd.receiving_unit_id = 0
AND cspd.payment_unit_id = #{paymentUnitId}
AND cspd.type = #{type}
AND (cspd.purchase_id = #{id} or cspd.project_id = #{id})

mapper.select:
SELECT
IFNULL(SUM(csp.actually_payment_amount),0)
FROM contract_supplier_payment AS csp
INNER JOIN scm_purchase_order AS spo ON csp.property_type = 1 AND csp.order_id = spo.id AND spo.bool_delete_enum
= 0
WHERE csp.bool_delete_enum = 0
AND csp.audit_status = 2

    AND csp.receiving_unit_id = #{supplierId}


    AND csp.order_id = #{orderId}


    AND spo.create_time >= #{startDate}


    AND spo.create_time <= #{endDate}

        SELECT IFNULL(SUM(breach_amount), 0)
        FROM contract_supplier_payment
        WHERE bool_delete_enum = 0
        AND bool_deduct = 1
        and audit_status = 2
        
            AND order_id = #{orderId}
        
        
            AND property_type = #{propertyType}
        
        
            AND receiving_unit_id = #{supplierId}

select *
from contract_supplier_payment
where bool_delete_enum = 0

    and project_id = #{projectId}


    and project_manager_id = #{projectManagerId}


    and supplier_id = #{supplierId}


    and serial_number like concat('%', #{purchaseContractNumber}, '%')

SELECT a.payment_amount as invoiceAmount, b.`name` as supplier, c.name as projectManagerName, d.`name` as 'project.name', d.id as 'project.id', d.short_name as 'project.shortName', d.serial_number as 'project.serialNumber' FROM contract_supplier_payment a LEFT JOIN scm_supplier b on a.supplier_id = b.id and b.bool_delete_enum = 0 LEFT JOIN sys_user c on a.project_manager_id = c.id and c.bool_delete_enum = 0 left join contract_project d on a.project_id = d.id and d.bool_delete_enum = 0 where a.bool_delete_enum = 0
and a.project_id = #{projectId}
and a.supplier_id = #{supplierId}

choose.otherwise:
SELECT temp.supplier_id AS id, (SELECT name FROM scm_supplier WHERE id = temp.supplier_id) supplier_name, IFNULL( sum( temp.freight ), 0 ) AS freight, count(*) AS train_number FROM ( SELECT sp.supplier_id, c.total_price AS freight FROM mes_building_cargo_list AS c INNER JOIN mes_building_supplier_price AS sp ON c.supplier_price_id = sp.id and sp.bool_personal_enum = 0 WHERE c.bool_delete_enum = 0 AND c.status IN ( 4, 8 )
AND ( c.project_id IN (SELECT id from contract_project where bool_delete_enum = 0 AND name LIKE concat ('%',#{name},'%')) OR sp.supplier_id IN ( SELECT id FROM scm_supplier WHERE bool_delete_enum = 0 AND name LIKE concat ('%',#{name},'%')) )
and date(c.create_time) >= date(#{startDate})
and date(c.create_time) <= date(#{endDate})
UNION ALL
SELECT supplier_id, freight FROM scm_logistics_order WHERE bool_delete_enum = 0 AND inbound_review_status = 2
AND ( purchase_SN like concat ('%',#{name},'%') OR supplier_id IN ( SELECT id FROM scm_supplier WHERE bool_delete_enum = 0 AND name like concat ('%',#{name},'%') ) )
and DATE(create_time) >= #{startDate}
and DATE(create_time) <= #{endDate}
) AS temp GROUP BY temp.supplier_id

mapper.select:
update contract_supplier_payment
set bool_delete_enum = 0
where id = #{id}
